@media(orientation:portrait){body.pf-game.playing #interactionOffer{bottom:calc(var(--safe-bottom,0px) + 82px);width:240px;max-width:calc(100vw - 32px);height:52px}}
@media(orientation:landscape) and (max-width:640px) and (max-height:380px){body.pf-game.playing #interactionOffer{width:220px;height:60px;bottom:calc(var(--safe-bottom,0px) + 8px)}}

body.pf-game.playing.interaction-offer-active .control-tip{visibility:hidden}
@media(orientation:portrait){body.pf-game.playing.interaction-offer-active:not(.gate-active) #playDetails{bottom:calc(var(--safe-bottom,0px) + 142px)}}

