import test from 'node:test';
import assert from 'node:assert/strict';
import {createShadowState,spawnShadowWorkers,stepShadowWorkers,clearShadowWorkers} from '../public/games/overtime-pinball/shadow-workers.js';
const world=()=>({halfWidth:18,top:-20,door:46.5,drain:50,gravity:6,stations:[],props:[],rails:[],gateClosed:false});
const make=(s,w=world(),options={})=>spawnShadowWorkers(s,{now:0,duration:12,count:2,origin:{x:0,z:0},velocity:{vx:0,vz:-20},world:w,view:'reverse',...options});
const single=(s,p={})=>s.workers.push({id:s.nextId++,x:0,z:0,vx:0,vz:0,r:.65,spawnedAt:0,expiresAt:12,contacts:{},dead:false,...p});
test('spawns at most two independent workers and does not mutate inputs',()=>{const s=createShadowState(),w=world(),before=JSON.stringify(w);make(s,w,{count:99});assert.equal(s.workers.length,2);assert.equal(JSON.stringify(w),before);make(s,w);assert.equal(s.workers.length,2);assert.notEqual(s.workers[0].contacts,s.workers[1].contacts);});
test('each worker disappears at expiry exactly once',()=>{const s=createShadowState();make(s);let e=stepShadowWorkers(s,{dt:.1,now:12,world:world()});assert.equal(e.filter(x=>x.reason==='expired').length,2);assert.equal(s.workers.length,0);assert.equal(stepShadowWorkers(s,{dt:.1,now:13,world:world()}).length,0);});
test('clear removes workers without resetting unique identity',()=>{const s=createShadowState();make(s);const id=s.nextId;clearShadowWorkers(s);assert.equal(s.workers.length,0);make(s);assert.ok(s.workers[0].id>=id);});
test('swept fast contact hits station at half points without passing through',()=>{const s=createShadowState();single(s,{x:-5,vx:44});const w=world();w.gravity=0;w.stations=[{id:'chair',type:'chair',x:0,z:0,r:1,power:15,points:25}];const e=stepShadowWorkers(s,{dt:.2,now:.2,world:w});assert.equal(e.filter(x=>x.type==='shadowHit').length,1);assert.equal(e[0].points,13);assert.ok(s.workers[0].x<0);assert.ok(s.workers[0].vx<0);});
test('drain kills only shadow, emits no primary gameplay event',()=>{const s=createShadowState();single(s,{z:49.9,vz:20});const e=stepShadowWorkers(s,{dt:.02,now:.02,world:world()});assert.deepEqual(e,[{type:'shadowRemoved',id:1,reason:'drain'}]);assert.equal(s.workers.length,0);});
test('zero dt does not move, collide, or expire (pause)',()=>{const s=createShadowState();make(s);const before=JSON.stringify(s);assert.deepEqual(stepShadowWorkers(s,{dt:0,now:20,world:world()}),[]);assert.equal(JSON.stringify(s),before);});
test('safe spawn refuses fully obstructed field',()=>{const s=createShadowState(),w=world();w.props=[{id:'wall',x:0,z:10,hx:18,hz:40}];make(s,w);assert.equal(s.workers.length,0);});
test('launcher and moving patrol never become shadow targets',()=>{const s=createShadowState();single(s,{x:-5,vx:44});const w=world();w.gravity=0;w.stations=[{id:'launcher',type:'launcher',x:0,z:0,r:1,points:100},{id:'patrol',patrol:true,x:2,z:0,r:1,points:100}];assert.deepEqual(stepShadowWorkers(s,{dt:.2,now:.2,world:w}),[]);assert.ok(s.workers[0].x>3);});
test('props bounce but never award; rectangles and copier protrusion are solid',()=>{for(const [station,point] of [[{id:'cab',type:'cabinet',x:0,z:0,hx:1,hz:3,points:20},{x:-5,z:0}],[{id:'copier',type:'copier',x:0,z:0,r:1,points:30},{x:-5,z:2.55}]]){const s=createShadowState();single(s,{...point,vx:44});const w={...world(),gravity:0,stations:[station]};const e=stepShadowWorkers(s,{dt:.2,now:.2,world:w,view:'reverse'});assert.ok(e.some(e=>e.type==='shadowHit'));assert.ok(s.workers[0].vx<0);}const s=createShadowState();single(s,{x:-5,vx:44});const e=stepShadowWorkers(s,{dt:.2,now:.2,world:{...world(),gravity:0,props:[{x:0,z:0,hx:1,hz:1}]}});assert.equal(e.length,0);assert.ok(s.workers[0].vx<0);});
test('continuous contact gives one award, leaving and returning permits another',()=>{const s=createShadowState();single(s,{x:-1.65,vx:1});const w={...world(),gravity:0,stations:[{id:'s',x:0,z:0,r:1,points:40,power:0}]};let total=0;for(let n=1;n<=30;n++){Object.assign(s.workers[0],{x:-1.65,z:0,vx:1,vz:0});total+=stepShadowWorkers(s,{dt:1/120,now:n/120,world:w}).filter(e=>e.type==='shadowHit').length;}assert.equal(total,1);Object.assign(s.workers[0],{x:-4,vx:0});stepShadowWorkers(s,{dt:1/120,now:.26,world:w});Object.assign(s.workers[0],{x:-1.7,vx:20});assert.equal(stepShadowWorkers(s,{dt:1/120,now:.28,world:w}).filter(e=>e.type==='shadowHit').length,1);});
test('door gate saves shadows without emitting rescue or progress',()=>{const w={...world(),gravity:0,gateClosed:true},s=createShadowState();single(s,{z:45,vz:30});assert.deepEqual(stepShadowWorkers(s,{dt:.1,now:.1,world:w}),[]);assert.ok(s.workers[0].vz<0);assert.ok(s.workers[0].z<46);});
test('static capsule and rising flipper bounce without awarding player save',()=>{const s=createShadowState();single(s,{z:4,vz:30});const flippers=[{side:'left',ax:-5,az:5,bx:5,bz:5,rising:true}];const e=stepShadowWorkers(s,{dt:.1,now:.1,world:{...world(),gravity:0},flippers});assert.deepEqual(e,[]);assert.ok(s.workers[0].vz<0);});
test('fixed steps agree at 30 and 60 fps, world and flippers remain read-only',()=>{const w={...world(),stations:[{id:'s',x:0,z:10,r:2,points:30,power:15}]},flippers=[{ax:-10,az:40,bx:-2,bz:42}];const before=JSON.stringify({w,flippers});const run=hz=>{const s=createShadowState();make(s,w,{duration:12});const events=[];for(let n=1;n<=hz*8;n++)events.push(...stepShadowWorkers(s,{dt:1/hz,now:n/hz,world:w,flippers}));return {s,events};};const a=run(30),b=run(60);assert.equal(a.events.length,b.events.length);assert.equal(a.s.workers.length,b.s.workers.length);a.s.workers.forEach((x,n)=>{assert.ok(Math.abs(x.x-b.s.workers[n].x)<1e-8);assert.ok(Math.abs(x.z-b.s.workers[n].z)<1e-8);});assert.equal(JSON.stringify({w,flippers}),before);});
test('moving flipper sweeps its stroke across a stationary worker',()=>{const s=createShadowState();single(s,{x:0,z:2,vx:0,vz:0});const flippers=[{side:'left',ax:-5,az:0,bx:5,bz:0,previous:{ax:-5,az:4,bx:5,bz:4},rising:true}];stepShadowWorkers(s,{dt:1/30,now:1/30,world:{...world(),gravity:0},flippers});assert.ok(s.workers[0].vz<0);});
test('real board spawn/15-second runs are bounded across views and frame rates',async()=>{const {readFileSync}=await import('node:fs');const actual=JSON.parse(readFileSync(new URL('./fixtures/shadow-world.json',import.meta.url)));for(const view of ['reverse','forward'])for(const hz of [30,60])for(let seed=0;seed<12;seed++){const s=createShadowState();const origin={x:(seed%3-1)*10,z:-10+Math.floor(seed/3)*12};make(s,actual,{origin,view,velocity:{vx:(seed-6)*3,vz:20}});assert.ok(s.workers.length<=2);for(const worker of s.workers){assert.ok(Math.abs(worker.x)<18);assert.ok(worker.z<46.5);}for(let n=1;n<=hz*15;n++){const e=stepShadowWorkers(s,{dt:1/hz,now:n/hz,world:actual,view});assert.ok(e.every(x=>x.type==='shadowHit'||x.type==='shadowRemoved'));for(const worker of s.workers){assert.ok([worker.x,worker.z,worker.vx,worker.vz].every(Number.isFinite));assert.ok(Math.hypot(worker.vx,worker.vz)<=44+1e-8);assert.ok(Object.keys(worker.contacts).length<=12);}}assert.equal(s.workers.length,0);}});

import {handlePlayCounts} from '../play-counts/index.mjs';
import {fighterEntryPath,handleFighterEntry} from '../play-counts/entries.mjs';
import {LeaderboardRepository} from './repository.mjs';
import {NOTE_FLOOR_MS} from '../../public/games/fast-hands/challenge.mjs';
export const BOARDS=Object.freeze({
 'long-jump':Object.freeze({rules:'journey-km-v1',unit:'km',status:'valid',direction:'desc',max:Number.MAX_VALUE}),
 hurdles:Object.freeze({rules:'110m-8h-v1',unit:'s',status:'done',direction:'asc',max:180}),
 'high-jump':Object.freeze({rules:'cleared-height-v1',unit:'m',status:'cleared',direction:'desc',max:Number.MAX_VALUE}),
 'pole-vault':Object.freeze({rules:'highest-feet-v1',unit:'m',status:'done',direction:'desc',max:Number.MAX_VALUE}),
 'shot-put':Object.freeze({rules:'relay-distance-v1',unit:'m',status:'valid',direction:'desc',max:Number.MAX_VALUE}),
 discus:Object.freeze({rules:'wind-ufo-distance-v1',unit:'m',status:'valid',direction:'desc',max:Number.MAX_VALUE}),
 'reaction-rod':Object.freeze({rules:'catch-rating-v1',unit:'catches',status:'done',direction:'desc',max:10,secondary:true}),
 'beer-slide':Object.freeze({rules:'accuracy-retention-v1',unit:'points',status:'valid',direction:'desc',max:10}),
 'tower-climb':Object.freeze({rules:'indoor-10floors-v1',unit:'s',status:'summit',direction:'asc',max:60})
});
// Existing schema requires score > 0: courtesy alone stores count + 1 and decodes API reads.
// Keep the encoded integer safe; no schema migration and no legacy-board score changes.
export const QA_COURTESY_BOARD=Object.freeze({rules:'press-courtesy-v2',unit:'courtesies',status:'seated',direction:'desc',max:Number.MAX_SAFE_INTEGER-1,integer:true,allowZero:true,storageOffset:1,secondary:true,secondaryDirection:'asc',secondaryMax:30,primaryMetric:'courtesies',secondaryMetric:'remaining'});
// Pacing revision is QA-only; keep all production contracts unchanged.
const QA_POLE_VAULT_BOARD=Object.freeze({...BOARDS['pole-vault'],rules:'real-altitude-v3'});
export const QA_RUNNER_BOARDS=Object.freeze({
 'run-400m':Object.freeze({rules:'400m-prototype-v3',unit:'s',status:'done',direction:'asc',min:30,max:3600,exclusiveMax:true}),
 'run-1500m':Object.freeze({rules:'1500m-rival-tiers-v5',unit:'s',status:'done',direction:'asc',max:Number.MAX_VALUE})
});
// Separate QA-only modes. Offset zero scores for the existing score>0 schema;
// retain the old schema and prevent this game's writes from pruning other boards.
const pinballBoard=rules=>Object.freeze({rules,unit:'points',status:'done',direction:'desc',max:Number.MAX_SAFE_INTEGER-1,integer:true,allowZero:true,storageOffset:1,isolateReceiptCleanup:true});
export const QA_PINBALL_BOARDS=Object.freeze({
 'overtime-pinball-60s':pinballBoard('office-overtime-flow-60-v3'),
 'overtime-pinball-180s':pinballBoard('office-overtime-flow-180-v3'),
 'overtime-pinball-unlimited':pinballBoard('office-overtime-flow-unlimited-v3')
});
const isPinball=game=>typeof game==='string'&&Object.hasOwn(QA_PINBALL_BOARDS,game);
// Fast Hands rules isolate the two input modes without changing the nine legacy boards.
export const FAST_HANDS_BOARDS=Object.freeze({
 mouse:Object.freeze({rules:'shuttle-v3-mouse',unit:'ms',status:'success',direction:'asc',max:NOTE_FLOOR_MS,exclusiveMax:true}),
 touch:Object.freeze({rules:'shuttle-v3-touch',unit:'ms',status:'success',direction:'asc',max:NOTE_FLOOR_MS,exclusiveMax:true})
});
export const LEVEL_BOARDS=Object.freeze({
 'fast-hands-catch':Object.freeze({rules:'cleared-levels-v1',unit:'levels',status:'done',direction:'desc',max:Number.MAX_SAFE_INTEGER,integer:true}),
 'fast-hands-duel':Object.freeze({rules:'ten-round-wins-v1',unit:'wins',status:'done',direction:'desc',max:10,integer:true})
});
const isLevel=game=>typeof game==='string'&&Object.hasOwn(LEVEL_BOARDS,game);
const isFast=game=>game==='fast-hands'||isLevel(game);
function resolveBoard(game,rules,scope){
 if(isPinball(game))return scope==='qa'?QA_PINBALL_BOARDS[game]:null;
 if(game==='courtesy-contest')return scope==='qa'?QA_COURTESY_BOARD:null;
 if(Object.hasOwn(QA_RUNNER_BOARDS,game))return scope==='qa'?QA_RUNNER_BOARDS[game]:null;
 if(scope==='qa'&&game==='pole-vault')return QA_POLE_VAULT_BOARD;
 if(isLevel(game))return LEVEL_BOARDS[game];
 if(game==='fast-hands')return Object.values(FAST_HANDS_BOARDS).find(board=>board.rules===rules)??null;
 return typeof game==='string'&&Object.hasOwn(BOARDS,game)?BOARDS[game]:null;
}
const fields=['game','rules','unit','status','score','nickname','deviceId','submissionId'];
const uuid=/^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
export function validateSubmission(value,scope){
 if(!value||Array.isArray(value)||typeof value!=='object'||(Object.keys(value).length!==fields.length&&Object.keys(value).length!==fields.length+1)||fields.some(k=>!Object.hasOwn(value,k))||Object.keys(value).some(k=>!fields.includes(k)&&k!=='secondaryScore'))throw Error('invalid_fields');
 if((isFast(value.game)||isPinball(value.game))&&Object.keys(value).length!==fields.length)throw Error('invalid_fields');
 const b=resolveBoard(value.game,value.rules,scope);if(!b||value.rules!==b.rules||value.unit!==b.unit||value.status!==b.status)throw Error('invalid_board');
 if(typeof value.score!=='number'||!Number.isFinite(value.score)||(b.allowZero?value.score<0:value.score<=0)||(b.min!==undefined&&value.score<b.min)||value.score>b.max||(b.integer&&!Number.isSafeInteger(value.score))||(b.exclusiveMax&&value.score===b.max))throw Error('invalid_score');
 if(b.secondary){if(!Number.isInteger(value.score)||typeof value.secondaryScore!=='number'||!Number.isFinite(value.secondaryScore)||value.secondaryScore<0||value.secondaryScore>(b.secondaryMax??10))throw Error('invalid_secondary');}
